    normalizeId(source.video_id),
    normalizeId(source.videoId),
    normalizeId(source.job_id),
    normalizeId(source.jobId),
    normalizeId(result.id),
    normalizeId(result.task_id),
    normalizeId(body.data?.id),
    normalizeId(body.data?.task_id),
    normalizeId(body.data?.taskId),
    normalizeId(body.task_id),
    normalizeId(body.id),
    normalizeId(source.videoPollId),
  );
}

function statusOf(source) {
  if (!source || typeof source !== 'object') return '';
  const body = source.body && typeof source.body === 'object' ? source.body : {};
  const data = source.data && typeof source.data === 'object' ? source.data : {};
  const result = source.result && typeof source.result === 'object' ? source.result : {};
  return pickFirstNonEmpty(
    data.status,
    data.state,
    result.status,
    result.state,
    body.data?.status,
    body.status,
    source.status,
    source.state,
    source.videoStatus,
  ).toLowerCase();
}

function findVideoUrl(value) {
  if (!value) return '';
  if (typeof value === 'string') {
    const normalized = value.toLowerCase();
    if ((value.startsWith('http://') || value.startsWith('https://')) && ['.mp4', '.mov', '.webm', '.m3u8'].some((ext) => normalized.includes(ext))) return value;
    return '';
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = findVideoUrl(entry);
      if (found) return found;
    }
    return '';
  }
  if (typeof value === 'object') {
    for (const key of ['videoFileUrl', 'result_url', 'video_url', 'url', 'download_url', 'origin_url']) {
      const found = findVideoUrl(value[key]);
      if (found) return found;
    }
    for (const nested of Object.values(value)) {
      const found = findVideoUrl(nested);
      if (found) return found;
    }
  }
  return '';
}

function failureMessageOf(source) {
  if (!source || typeof source !== 'object') return String(source || '').trim();
  const error = source.error;
  return pickFirstNonEmpty(
    source.message,
    source.fail_reason,
    source.reason,
    source.statusMessage,
    error && typeof error === 'object' ? error.message : error,
    source.data?.message,
    source.data?.fail_reason,
    source.result?.message,
  );
}

function httpStatusOf(...sources) {
  for (const source of sources) {
    if (!source || typeof source !== 'object') continue;
    const candidates = [
      source.statusCode,
      source.status_code,
      source.httpStatus,
      source.http_status,
      source.code,
      source.response?.statusCode,
      source.response?.status,
      source.error?.statusCode,
      source.error?.status,
      source.error?.code,
      source.error?.response?.statusCode,
      source.error?.response?.status,
      source.error?.cause?.statusCode,
      source.error?.cause?.status,
    ];
    for (const candidate of candidates) {
      const code = Number(candidate);
      if (Number.isInteger(code) && code >= 100 && code < 600) return code;
    }
  }
  return 0;
}

function collectProviderText(value, depth = 0, seen = new Set()) {
  if (value === null || value === undefined || depth > 4) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (typeof value !== 'object' || seen.has(value)) return '';
  seen.add(value);
  const parts = [];
  for (const [key, nested] of Object.entries(value)) {
    if (['apiKey', 'videoApiKey', 'imageApiKey', 'Authorization'].includes(key)) continue;
    parts.push(key, collectProviderText(nested, depth + 1, seen));
  }
  return parts.filter(Boolean).join(' ');
}

function isNonRetryableFailure(source, message, providerResponse) {
  const statusCode = httpStatusOf(providerResponse, source);
  if (statusCode >= 400 && statusCode < 500 && ![408, 409, 425, 429].includes(statusCode)) return true;

  const text = [message, collectProviderText(providerResponse), collectProviderText(source)].join(' ').toLowerCase();
  return [
    'invalid api key',
    'unauthorized',
    'forbidden',
    'permission denied',
    'bad request',
    'invalid request',
    'insufficient balance',
    'quota exceeded',
    '参数错误',
    '参数无效',
    '鉴权',
    '无权限',
    '余额不足',
  ].some((needle) => text.includes(needle));
}

function retryDelayMs(source, attempt) {
  const base = Math.max(1000, Number(source.config?.videoRetryDelayMs || source.videoRetryDelayMs || 30000));
  const cap = Math.max(base, Number(source.config?.videoMaxRetryDelayMs || source.videoMaxRetryDelayMs || 180000));
  return Math.min(cap, base * Math.max(1, attempt));
}

function withDerivedVideoFields(source) {
  const videoId = jobIdOf(source);
  const videoFileUrl = findVideoUrl(source);
  return {
    ...source,
    videoPollId: videoId || source.videoPollId || '',
    videoFileUrl: videoFileUrl || source.videoFileUrl || '',
    videoStatus: statusOf(source) || source.videoStatus || '',
    provider_last_response: source.provider_last_response || source,
  };
}

function mergeResponse(source, payload) {
  const body = payload && typeof payload === 'object' ? payload : { body: payload };
  return withDerivedVideoFields({
    ...source,
    ...body,
    status: statusOf(body) || statusOf(source),
    provider_last_response: body,
  });
}

function retryOrFail(source, reason, providerResponse) {
  const attempt = Math.max(1, Number(source.videoAttempt || 1));
  const maxAttempts = Math.max(1, Number(source.config?.videoMaxAttempts || source.videoMaxAttempts || 3));
  const message = reason || failureMessageOf(providerResponse) || failureMessageOf(source) || 'Video generation failed.';

  const retryable = !isNonRetryableFailure(source, message, providerResponse);
  const nextDelayMs = retryDelayMs(source, attempt);

  if (attempt < maxAttempts && retryable) {
    return [{
      json: {
        ...source,
        status: 'retry',
        videoAttempt: attempt + 1,
        videoRetryCount: attempt,
        videoMaxAttempts: maxAttempts,
        videoLastFailureMessage: message,
        videoLastFailedTaskId: jobIdOf(source),
        videoPollId: '',
        videoStatusUrl: '',
        videoStatus: '',
        videoFileUrl: '',
        videoPollAttempt: 0,
        videoPollStartedAtMs: '',
        videoPollDeadlineAtMs: '',
        videoRetryDelayMs: nextDelayMs,
        videoPollDelayMs: nextDelayMs,
        provider_last_response: providerResponse || source.provider_last_response || null,
      },
    }];
  }

  return [{
    json: {
      ...source,
      status: 'failed',
      message,
      videoAttempt: attempt,
      videoRetryCount: Math.max(0, attempt - 1),
      videoMaxAttempts: maxAttempts,
      videoProviderRetryable: retryable,
      provider_last_response: providerResponse || source.provider_last_response || null,
    },
  }];
}

const intervalMs = Math.max(1000, Number(state.videoPollIntervalMs || state.config?.pollIntervalMs || 10000));
const attempt = Number(state.videoPollAttempt || 0) + 1;
let current = withDerivedVideoFields({
  ...state,
  videoPollAttempt: attempt,
  videoPollDelayMs: intervalMs,
});

const deadlineMs = Number(current.videoPollDeadlineAtMs || 0);
if (deadlineMs && Date.now() > deadlineMs) {
  return retryOrFail(current, 'Video job polling timed out after ' + Number(current.config?.videoTimeoutMs || 40 * 60 * 1000) + 'ms.', current.provider_last_response || current);
}

if (response?.error) {
  return retryOrFail(current, failureMessageOf(response) || 'Video status request failed.', response);
}

current = mergeResponse(current, response);
const currentStatus = statusOf(current);

if (done.has(currentStatus) || findVideoUrl(current)) {
  return [{ json: { ...current, status: 'completed', videoStatus: currentStatus || 'completed' } }];
}
if (failed.has(currentStatus)) {
  return retryOrFail(current, failureMessageOf(response), response);
}

return [{
  json: {
    ...current,
    status: 'pending',
    videoStatus: currentStatus || 'pending',
    videoPollAttempt: attempt,
    videoPollDelayMs: intervalMs,
  },
}];
